561	    /**
562	     * Applies the owner's address on create from the structured fields when present, falling back to the
563	     * flat {@code address} for backward compatibility. An owner must supply an address in at least one
564	     * form: a non-blank {@code addressLine1} (the structured form, preferred) or a non-blank flat
565	     * {@code address}; when neither is present the create is rejected.
566	     * <p>
567	     * Whichever address fields are supplied are normalized (see {@link #normalizeAddress}). When the
568	     * structured form is used the normalized {@code addressLine1} and, when supplied, {@code addressLine2}
569	     * are stored on the owner and the composed {@code address} is the normalized {@code addressLine1} with
570	     * a single space and the normalized {@code addressLine2} appended when {@code addressLine2} is present.
571	     * When only the flat form is used the normalized flat value becomes the stored {@code address} and the
572	     * structured lines are left unset. The stored {@code address} is the value every later step reads.
573	     *
574	     * @param owner the owner being created
575	     * @param ownerFieldsDto the submitted owner fields carrying the raw address input
576	     * @throws InvalidAddressException (400 Bad Request) if no address is supplied in either form
577	     */
578	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
579	        String rawLine1 = ownerFieldsDto.getAddressLine1();
580	        String rawLine2 = ownerFieldsDto.getAddressLine2();
581	        String rawFlat = ownerFieldsDto.getAddress();
582	        boolean hasLine1 = rawLine1 != null && !rawLine1.isBlank();
583	        boolean hasFlat = rawFlat != null && !rawFlat.isBlank();
584	        if (!hasLine1 && !hasFlat) {
585	            throw new InvalidAddressException(rawLine1 != null ? rawLine1 : rawFlat);
586	        }
587	        if (hasLine1) {
588	            String line1 = normalizeAddress(rawLine1);
589	            String line2 = (rawLine2 != null && !rawLine2.isBlank()) ? normalizeAddress(rawLine2) : null;
590	            owner.setAddressLine1(line1);
591	            owner.setAddressLine2(line2);
592	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
593	        } else {
594	            owner.setAddressLine1(null);
595	            owner.setAddressLine2(null);
596	            owner.setAddress(normalizeAddress(rawFlat));
597	        }
598	    }
