600	    /**
601	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
602	     * whitespace collapse to a single space, the value is upper-cased and common street-type
603	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
604	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
605	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
606	     * for every address comparison (household duplicate detection and the shared household id).
607	     *
608	     * @param address the raw address as submitted
609	     * @return the normalized address
610	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
611	     */
612	    private String normalizeAddress(String address) {
613	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
614	        if (collapsed.isEmpty()) {
615	            throw new InvalidAddressException(address);
616	        }
617	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
618	        StringBuilder normalized = new StringBuilder(collapsed.length());
619	        for (int i = 0; i < tokens.length; i++) {
620	            if (i > 0) {
621	                normalized.append(' ');
622	            }
623	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
624	        }
625	        return normalized.toString();
626	    }
627	
628	    /**
629	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
630	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
631	     * owners are duplicates when they share the same normalized telephone and the same normalized email
632	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
633	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
634	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
635	     * still match.
636	     * <p>
637	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
638	     * grouping, so two members of the same household with different telephones have different
639	     * identities and are both allowed. Only owners with the same telephone and email collide.
640	     *
641	     * @param owner the owner being created, with its telephone and email already normalized
642	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
643	     */
644	    private void rejectDuplicateIdentity(Owner owner) {
645	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
646	        boolean duplicate = this.clinicService.findAllOwners().stream()
647	            .anyMatch(existing -> identity.equals(
648	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
649	        if (duplicate) {
650	            String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
651	            throw new DuplicateIdentityException(
652	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
653	        }
654	    }
655	
656	    /**
657	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
658	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
659	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
660	     */
661	    private String personalIdentity(String telephone, String email) {
662	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
663	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
664	    }
665	
666	    /**
667	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
668	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
669	     * when its national-number length does not match its country code.
670	     */
671	    private String toE164OrNull(String telephone) {
672	        try {
673	            return normalizeTelephone(telephone);
674	        } catch (InvalidTelephoneException e) {
675	            return null;
676	        }
677	    }
678	
679	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
680	    @Override
681	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
682	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
683	        if (currentOwner == null) {
684	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
685	        }
686	        currentOwner.setAddress(ownerFieldsDto.getAddress());
687	        currentOwner.setCity(ownerFieldsDto.getCity());
688	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
689	        currentOwner.setLastName(ownerFieldsDto.getLastName());
690	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
691	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
692	        this.clinicService.saveOwner(currentOwner);
693	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
694	    }
695	
696	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
697	    @Transactional
698	    @Override
699	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
700	        Owner owner = this.clinicService.findOwnerById(ownerId);
701	        if (owner == null) {
702	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
703	        }
704	        this.clinicService.deleteOwner(owner);
705	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
706	    }
707	
708	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
709	    @Override
710	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
711	        Owner owner = this.clinicService.findOwnerById(ownerId);
712	        if (owner == null) {
713	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
714	        }
715	        HttpHeaders headers = new HttpHeaders();
716	        Pet pet = petMapper.toPet(petFieldsDto);
717	        owner.setId(ownerId);
718	        pet.setOwner(owner);
719	        pet.getType().setName(null);
720	        this.clinicService.savePet(pet);
721	        PetDto petDto = petMapper.toPetDto(pet);
722	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
723	            .buildAndExpand(pet.getId()).toUri());
724	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
725	    }
726	
727	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
728	    @Override
729	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
730	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
731	        if (currentOwner != null) {
732	            Pet currentPet = this.clinicService.findPetById(petId);
733	            if (currentPet != null) {
734	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
735	                currentPet.setName(petFieldsDto.getName());
736	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
737	                this.clinicService.savePet(currentPet);
738	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
739	            }
740	        }
741	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
742	    }
743	
744	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
745	    @Override
746	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
747	        HttpHeaders headers = new HttpHeaders();
748	        Visit visit = visitMapper.toVisit(visitFieldsDto);
749	        Pet pet = new Pet();
750	        pet.setId(petId);
751	        visit.setPet(pet);
752	        this.clinicService.saveVisit(visit);
753	        VisitDto visitDto = visitMapper.toVisitDto(visit);
754	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
755	            .buildAndExpand(visit.getId()).toUri());
756	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
757	    }
758	
759	
760	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
761	    @Override
762	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
763	        Owner owner = this.clinicService.findOwnerById(ownerId);
764	        if (owner != null) {
765	            Pet pet = owner.getPet(petId);
766	            if (pet != null) {
767	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
768	            }
769	        }
770	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
771	    }
772	}
